    static List<List<Integer>> adj;
    static int[] color;
    static boolean cycle;
    static void dfs(int u) {
        color[u] = 1;
        for (int v : adj.get(u)) {
            if (color[v] == 1) { cycle = true; return; }
            if (color[v] == 0) { dfs(v); if (cycle) return; }
        }
        color[u] = 2;
    }
