public class Main {
    static int[] parent, rank;
    static int find(int x) { if (parent[x] != x) parent[x] = find(parent[x]); return parent[x]; }
    static boolean union(int a, int b) {
        a = find(a); b = find(b); if (a == b) return false;
        if (rank[a] < rank[b]) { int t = a; a = b; b = t; }
        parent[b] = a; if (rank[a] == rank[b]) rank[a]++;
        return true;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken()), M = Integer.parseInt(st.nextToken());
        parent = new int[N+1]; rank = new int[N+1];
        for (int i = 0; i <= N; i++) parent[i] = i;
        boolean cycle = false;
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()), v = Integer.parseInt(st.nextToken());
            if (!union(u, v)) cycle = true;
        }
        System.out.println(cycle ? "CYCLE" : "NO_CYCLE");
    }
}

