int find(int x) { if (parent[x] != x) parent[x] = find(parent[x]); return parent[x]; }
bool unite(int a, int b) {
    a = find(a); b = find(b); if (a == b) return false;
    if (rnk[a] < rnk[b]) swap(a, b);
    parent[b] = a;
    if (rnk[a] == rnk[b]) rnk[a]++;
    return true;
}

int main() {
