            if (d > dist[u]) continue;
            for (long[] e : adj[u]) { int v=(int)e[0]; long w=e[1];
                if (dist[u]+w < dist[v]) { dist[v]=dist[u]+w; pq.offer(new long[]{dist[v],v}); }
            }
