                a, b = char_idx.get(c1, -1), char_idx.get(c2, -1)
                if a == -1 or b == -1: break
                adj[a].append(b); indegree[b] += 1; found = True; break
        if not found and len(w1) > len(w2): valid = False; break
    if not valid: print('INVALID'); return
    queue = deque(i for i in range(K) if indegree[i] == 0)
    order = []
    while queue:
        u = queue.popleft(); order.append(chars[u])
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0: queue.append(v)
    if len(order) == K: print(''.join(order))
    else: print('INVALID')

