using namespace std;

struct DSU {
    vector<int> parent, sz;
    DSU(int n) : parent(n), sz(n, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int i) { return parent[i] == i ? i : parent[i] = find(parent[i]); }
    void unite(int i, int j) {
        int ri = find(i), rj = find(j);
        if (ri != rj) {
            if (sz[ri] < sz[rj]) swap(ri, rj);
            parent[rj] = ri; sz[ri] += sz[rj];
        }
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    long long N, M; if (!(cin >> N >> M)) return 0;
    DSU dsu(N);
    for (int i = 0; i < M; i++) {
        int u, v; cin >> u >> v; dsu.unite(u, v);
    }
    long long total = N * (N - 1) / 2;
    for (int i = 0; i < N; i++) {
        if (dsu.parent[i] == i) {
            long long s = dsu.sz[i];
            total -= s * (s - 1) / 2;
        }
    }
    cout << total << "\n";
    return 0;
}

