        if (C > Math.max(A, B) || C % gcd(A, B) != 0) { System.out.println(-1); return; }
        if (C == A || C == B) { System.out.println(1); return; }
        Set<Long> visited = new HashSet<>();
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{0, 0, 0});
