#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N, M, src, dst, K;
    if (!(cin >> N >> M >> src >> dst >> K)) return 0;
    struct Edge { int u, v, w; };
    vector<Edge> edges(M);
    for (int i = 0; i < M; i++) cin >> edges[i].u >> edges[i].v >> edges[i].w;
    const long long INF = 1e18;
    vector<long long> dist(N, INF);
    dist[src] = 0;
    for (int step = 0; step <= K; step++) {
        vector<long long> temp = dist;
        for (auto& e : edges) {
            if (dist[e.u] != INF && dist[e.u] + e.w < temp[e.v]) {
                temp[e.v] = dist[e.u] + e.w;
            }
        }
        dist = temp;
    }
    cout << (dist[dst] >= INF ? -1 : dist[dst]) << "\n";
    return 0;
}

