public class Main {
    static List<int[]>[] adj;
    static boolean[] visited;
    static boolean found = false;
    static int K;
    static void dfs(int u, int curLen) {
        if (curLen >= K) { found = true; return; }
        for (int[] edge : adj[u]) {
            int v = edge[0], w = edge[1];
            if (!visited[v]) {
                visited[v] = true;
                dfs(v, curLen + w);
                visited[v] = false;
                if (found) return;
            }
        }
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        StringTokenizer st = new StringTokenizer(line);
        int N = Integer.parseInt(st.nextToken()), M = Integer.parseInt(st.nextToken());
        K = Integer.parseInt(st.nextToken());
        adj = new List[N];
        for (int i = 0; i < N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()), v = Integer.parseInt(st.nextToken()), w = Integer.parseInt(st.nextToken());
            adj[u].add(new int[]{v, w}); adj[v].add(new int[]{u, w});
        }
        visited = new boolean[N];
        visited[0] = true;
        dfs(0, 0);
        System.out.println(found ? "EXISTS" : "NONE");
    }
}

