    if not input_data: return
    N, M, K = int(input_data[0]), int(input_data[1]), int(input_data[2])
    adj = [[] for _ in range(N + 1)]
    idx = 3
    for _ in range(M):
        u, v = int(input_data[idx]), int(input_data[idx+1]); idx += 2
        adj[u].append(v); adj[v].append(u)

    color = [0] * (N + 1)

    def is_safe(node, c):
        for neighbor in adj[node]:
            if color[neighbor] == c:
                return False
        return True

    def backtrack(node):
        if node > N:
            return True
        for c in range(1, K + 1):
            if is_safe(node, c):
                color[node] = c
                if backtrack(node + 1):
                    return True
                color[node] = 0
        return False

    print('FEASIBLE' if backtrack(1) else 'INFEASIBLE')

if __name__ == '__main__':
    solve()

