            if (net[deb] == 0 && net[cred] == 0) break;
            long amt = Math.min(-net[deb], net[cred]);
            net[deb] += amt; net[cred] -= amt;
            tx.add(deb + " " + cred + " " + amt);
        }
        System.out.println(tx.size());
        for (String s : tx) System.out.println(s);
    }
}

