import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data: return
    N = int(input_data[0])
    r1, c1 = int(input_data[1]), int(input_data[2])
    r2, c2 = int(input_data[3]), int(input_data[4])
    if (r1, c1) == (r2, c2):
        print(0); return

    moves = [
        (-2, -1), (-2, 1), (-1, -2), (-1, 2),
        (1, -2), (1, 2), (2, -1), (2, 1)
    ]
    dist = {}
    dist[(r1, c1)] = 0
    queue = deque([(r1, c1)])
    while queue:
        r, c = queue.popleft()
        d = dist[(r, c)]
        if (r, c) == (r2, c2):
            print(d); return
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 1 <= nr <= N and 1 <= nc <= N and (nr, nc) not in dist:
                dist[(nr, nc)] = d + 1
                if (nr, nc) == (r2, c2):
                    print(d + 1); return
                queue.append((nr, nc))
    print(-1)

if __name__ == '__main__':
