import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        StringTokenizer st = new StringTokenizer(line);
        String begin = st.nextToken(), end = st.nextToken();
        if (begin.equals(end)) { System.out.println(1); return; }
        int K = Integer.parseInt(br.readLine().trim());
        Set<String> wordSet = new HashSet<>();
        st = new StringTokenizer(br.readLine());
        while (st.hasMoreTokens()) wordSet.add(st.nextToken());
        if (!wordSet.contains(end)) { System.out.println(0); return; }
        int L = begin.length();
        Map<String, List<String>> patterns = new HashMap<>();
        for (String w : wordSet) {
            for (int i = 0; i < L; i++) {
                String p = w.substring(0, i) + "*" + w.substring(i + 1);
                patterns.computeIfAbsent(p, k -> new ArrayList<>()).add(w);
            }
        }
        ArrayDeque<String> q = new ArrayDeque<>();
        ArrayDeque<Integer> steps = new ArrayDeque<>();
        q.add(begin); steps.add(1);
        Set<String> visited = new HashSet<>();
        visited.add(begin);
        while (!q.isEmpty()) {
            String curr = q.poll();
            int step = steps.poll();
            for (int i = 0; i < L; i++) {
                String p = curr.substring(0, i) + "*" + curr.substring(i + 1);
                List<String> neighbors = patterns.getOrDefault(p, Collections.emptyList());
                for (String nb : neighbors) {
                    if (nb.equals(end)) { System.out.println(step + 1); return; }
                    if (!visited.contains(nb)) {
                        visited.add(nb); q.add(nb); steps.add(step + 1);
                    }
                }
            }
        }
        System.out.println(0);
    }
}

