#include <string>
#include <queue>
#include <unordered_set>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    string begin, end; if (!(cin >> begin >> end)) return 0;
    if (begin == end) { cout << 1 << "\n"; return 0; }
    int K; if (!(cin >> K)) return 0;
    unordered_set<string> wordSet;
    for (int i = 0; i < K; i++) { string s; cin >> s; wordSet.insert(s); }
    if (!wordSet.count(end)) { cout << 0 << "\n"; return 0; }
    int L = begin.size();
    unordered_map<string, vector<string>> patterns;
    for (const auto& w : wordSet) {
        for (int i = 0; i < L; i++) {
            string p = w; p[i] = '*';
            patterns[p].push_back(w);
        }
    }
    queue<pair<string, int>> q;
    q.push({begin, 1});
    unordered_set<string> visited;
    visited.insert(begin);
    while (!q.empty()) {
        auto [curr, step] = q.front(); q.pop();
        for (int i = 0; i < L; i++) {
            string p = curr; p[i] = '*';
            for (const auto& nb : patterns[p]) {
                if (nb == end) { cout << step + 1 << "\n"; return 0; }
                if (!visited.count(nb)) {
                    visited.insert(nb); q.push({nb, step + 1});
                }
            }
            patterns[p].clear();
        }
    }
    cout << 0 << "\n";
    return 0;
}

