import sys

def determinant(matrix):
    n = len(matrix)
    A = [row[:] for row in matrix]
    det = 1.0
    for i in range(n):
        pivot = i
        for j in range(i + 1, n):
            if abs(A[j][i]) > abs(A[pivot][i]):
                pivot = j
        if abs(A[pivot][i]) < 1e-9:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            det = -det
        det *= A[i][i]
        for j in range(i + 1, n):
            factor = A[j][i] / A[i][i]
            for k in range(i + 1, n):
                A[j][k] -= factor * A[i][k]
    return round(det)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data: return
    N, M = int(input_data[0]), int(input_data[1])
    laplacian = [[0.0] * N for _ in range(N)]
    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        idx += 2
        laplacian[u][u] += 1
        laplacian[v][v] += 1
        laplacian[u][v] -= 1
        laplacian[v][u] -= 1

    submatrix = [laplacian[i][:N-1] for i in range(N-1)]
    print(int(determinant(submatrix)))

if __name__ == '__main__':
    solve()

