import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data: return
    N, M = int(input_data[0]), int(input_data[1])
    dist = [[float('inf')] * (N + 1) for _ in range(N + 1)]
    deg = [0] * (N + 1)
    total_edge_weight = 0
    idx = 2
    for i in range(1, N + 1): dist[i][i] = 0
    for _ in range(M):
        u = int(input_data[idx]); v = int(input_data[idx+1]); w = int(input_data[idx+2]); idx += 3
        deg[u] += 1; deg[v] += 1
        dist[u][v] = min(dist[u][v], w)
        dist[v][u] = min(dist[v][u], w)
        total_edge_weight += w

    # Floyd-Warshall for all-pairs shortest paths
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    odd_nodes = [i for i in range(1, N + 1) if deg[i] % 2 != 0]
    K = len(odd_nodes)
    if K == 0:
        print(total_edge_weight); return

    memo = {}
    def min_weight_matching(mask):
        if mask == 0: return 0
        if mask in memo: return memo[mask]
        # Find first set bit
        first = -1
        for i in range(K):
            if (mask & (1 << i)):
                first = i; break
        res = float('inf')
        for second in range(first + 1, K):
            if (mask & (1 << second)):
                cost = dist[odd_nodes[first]][odd_nodes[second]]
                rem = mask ^ (1 << first) ^ (1 << second)
                res = min(res, cost + min_weight_matching(rem))
        memo[mask] = res
        return res

    print(total_edge_weight + min_weight_matching((1 << K) - 1))

if __name__ == '__main__':
    solve()

