        adj_matrix[v][u] = True

    # Build complement graph: edge if NOT connected in original
    comp_adj = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            if not adj_matrix[i][j]:
                comp_adj[i].append(j)
                comp_adj[j].append(i)

    # Check if complement graph is bipartite
    color = [0] * (N + 1)
    for start in range(1, N + 1):
        if color[start] == 0:
            color[start] = 1
            queue = deque([start])
            while queue:
                u = queue.popleft()
                for v in comp_adj[u]:
                    if color[v] == 0:
                        color[v] = 3 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        print('IMPOSSIBLE'); return

    print('POSSIBLE')

if __name__ == '__main__':
    solve()

