import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        StringTokenizer st = new StringTokenizer(line);
        int N = Integer.parseInt(st.nextToken()), M = Integer.parseInt(st.nextToken());
        if (N <= 2) { System.out.println("POSSIBLE"); return; }
        boolean[][] original = new boolean[N + 1][N + 1];
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()), v = Integer.parseInt(st.nextToken());
            original[u][v] = original[v][u] = true;
        }
        List<Integer>[] comp = new List[N + 1];
        for (int i = 0; i <= N; i++) comp[i] = new ArrayList<>();
        for (int i = 1; i <= N; i++) {
            for (int j = i + 1; j <= N; j++) {
                if (!original[i][j]) {
                    comp[i].add(j); comp[j].add(i);
                }
            }
        }
        int[] color = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            if (color[i] == 0) {
                color[i] = 1;
                ArrayDeque<Integer> q = new ArrayDeque<>();
                q.add(i);
                while (!q.isEmpty()) {
                    int u = q.poll();
                    for (int v : comp[u]) {
                        if (color[v] == 0) {
                            color[v] = 3 - color[u];
                            q.add(v);
                        } else if (color[v] == color[u]) {
                            System.out.println("IMPOSSIBLE"); return;
                        }
                    }
                }
            }
        }
        System.out.println("POSSIBLE");
    }
}

